-- DB update 2026_10_30_01 -> 2026_10_30_02
-- Vanilla 1.12.1 mana costs for player damage/heal spells.
-- Source: cmangos/classic-db 1.12.1 z2815 (classic_world.spell_template), matched by spell id
-- against acore_world.spell_ranks; only ranks with SpellLevel <= 60 and a positive vanilla ManaCost.
-- The core applies this flat cost before talent/aura cost modifiers (SpellInfo::CalcPowerCost).
-- Idempotent: table is recreated if absent and fully repopulated.

CREATE TABLE IF NOT EXISTS `vanilla_spell_cost` (
  `spell_id` int unsigned NOT NULL,
  `mana_cost` int unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`spell_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELETE FROM `vanilla_spell_cost`;

